local function number(v,lo,hi)return type(v)=='number'and v==v and v>=lo and v<=hi end
function F.Validate(r)
 if type(r)~='table'or getmetatable(r)then return nil,'Invalid effect controls'end
 local rules={animation={0,2000},speed={.1,2},particles={.1,3},animationKit={0,10000000},spellKit={0,10000000}}
 local out={};for k,v in pairs(r)do
  if k=='source'then if type(v)~='string'or #v>180 or v:find('[%c|]')then return nil,'Use a short plain source reference'end
  elseif k=='loop'then if type(v)~='boolean'then return nil,'Invalid effect loop'end
  elseif not rules[k]or not number(v,rules[k][1],rules[k][2])or(k~='speed'and k~='particles'and v~=math.floor(v))then return nil,'Invalid effect '..tostring(k)end;out[k]=v
 end
 if((out.animationKit or 0)>0 or(out.spellKit or 0)>0)and(not out.source or #out.source<8)then return nil,'Kit IDs require an actual client/reference source; IDs are never guessed'end
 return out
end
function F.Apply(a,r)
 local N=ns.WardenNativeScene;local valid,why=F.Validate(r);if not valid then return false,why end
 if not a or not a.ready then return false,'Wait for the native effect model'end
 local report={status='API requests only; inspect visually in Forever',fileID=a.spec.fileID,controls=valid,methods={},boundsSource=a.effectBoundsSource or'native bounds'}
 local function call(method,...)
  if type(a.actor[method])~='function'then report.methods[method]='unavailable';return false end
  local ok,result=N.Call(a.actor,method,...);report.methods[method]=ok and result~=false and'accepted; visual behavior unverified'or'rejected';return ok and result~=false
 end
 call('SetParticleOverrideScale',valid.particles or 1)
 -- Clear previous kits when changing settings, never stack recurring casts.
 call('StopAnimationKit');call('SetSpellVisualKit',0,false)
 if(valid.animationKit or 0)>0 then call('PlayAnimationKit',valid.animationKit,valid.loop==true)
 elseif valid.animation~=nil then call('SetAnimation',valid.animation,0,valid.speed or 1,0)end
 if(valid.spellKit or 0)>0 then call('SetSpellVisualKit',valid.spellKit,not valid.loop)end
 a.effectReport=report;return true,report
end
function F.LightCapabilities(view)
 local out={};for _,method in ipairs({'SetLightAmbientColor','SetLightDiffuseColor','SetLightDirection','SetLightPosition','SetLightType'})do out[method]=view and type(view[method])=='function'or false end
 local e=Enum and Enum.ModelLightType;out.pointEnum=e and e.Point~=nil or false
 out.visualVerification='NOT VERIFIED in Forever';return out
end
function F.ApplyLight(view,r,shot)
 local N=ns.WardenNativeScene;local out=F.LightCapabilities(view)
 if not r then return out end
 local v,why=ns.WardenSceneObjectControls.Light(r);if not v then out.error=why;return out end
 out.request=v;out.background='Native models only; baked 2D artwork does not receive this light'
 if v.mode=='point'and not(out.pointEnum and out.SetLightPosition and out.SetLightType)then
  out.error='Point light unavailable; default scene light retained';return out
 end
 local function call(method,...)local ok,result=N.Call(view,method,...);out[method]=ok and result~=false;return out[method]end
 call('SetLightAmbientColor',v.red*v.ambient,v.green*v.ambient,v.blue*v.ambient)
 call('SetLightDiffuseColor',v.red*v.diffuse,v.green*v.diffuse,v.blue*v.diffuse)
 local e=Enum and Enum.ModelLightType
 if v.mode=='point'then
  if out.pointEnum and out.SetLightPosition and out.SetLightType then
   local x,y,z=v.x,v.y,v.z;if shot then x,y,z=N.World(shot,x,y,z)end
   out.nativePosition={x,y,z};call('SetLightType',e.Point);call('SetLightPosition',x,y,z)
  else out.error='Point light unavailable; directional scene light retained'end
 else
  if e and e.Directional~=nil then call('SetLightType',e.Directional)end
  call('SetLightDirection',v.x,v.y,v.z)
 end
 out.request=v;out.background='Native models only; baked 2D artwork does not receive this light';return out
end
